75|   | 0 => { δ | χ ➝ δ ∈ T.theory }
76|   | i + 1 =>
77|     match (decode i) with
78|     | some δ =>
79|       letI T' := construction T hT i
80|       if ∀ Γ : Finset (Formula _), ↑Γ ⊆ T' → Γ.conj ⋏ δ ➝ ξ ∉ T.theory then insert δ T'
81|       else T'
82|     | none => construction T hT i
