313| abbrev emptyPrimeFTheory (L : Logic _) [Entailment.F L] [Entailment.Disjunctive L] : PrimeFTheory L where
314|   theory := L
315|   no_bot := by
316|     sorry;
317|   andIR hφ hψ := by
318|     simp only [←Logic.iff_provable] at hφ hψ ⊢;
319|     apply andIR <;> assumption;
320|   imp_closed := by
321|     intros φ ψ hφψ hφ;
322|     simp only [←Logic.iff_provable] at hφψ hφ ⊢;
323|     exact hφψ ⨀ hφ;
324|   L_subset := by tauto;
325|   prime {φ ψ} hφψ := by
326|     simp only [←Logic.iff_provable] at hφψ ⊢;
327|     exact disjunctive hφψ;
328| 
329| instance [Entailment.F L] [Entailment.Disjunctive L] : Nonempty (PrimeFTheory L) := ⟨emptyPrimeFTheory L⟩
