334| variable {Ax : Axiom ℕ} {φ ψ χ : Formula ℕ}
335| variable [Entailment.F L] [Entailment.Disjunctive L]
336| 
337| open Formula.Kripke2
338| 
339| abbrev canonicalModel (L : Logic ℕ) [Entailment.F L] [Entailment.Disjunctive L] : Kripke2.Model where
340|   World := PrimeFTheory L
341|   Rel T U := ∀ {φ ψ}, φ ➝ ψ ∈ T.theory → φ ∈ U.theory → ψ ∈ U.theory
342|   Val T a := (atom a) ∈ T.theory
343|   root := emptyPrimeFTheory L
344|   rooted := by
345|     intro T φ ψ hφψ hφ;
346|     rw [←Logic.iff_provable] at hφψ;
347|     exact T.imp_closed hφψ hφ;
348| 
349| lemma truthlemma {T : canonicalModel L} : Satisfies _ T φ ↔ φ ∈ T.theory := by
350|   induction φ generalizing T with
351|   | hatom a => simp [Kripke2.Satisfies];
352|   | hfalsum => simp [Kripke2.Satisfies];
353|   | hor φ ψ ihφ ihψ =>
354|     suffices φ ∈ T.theory ∨ ψ ∈ T.theory ↔ φ ⋎ ψ ∈ T.theory by
355|       simpa [Kripke2.Satisfies, ihφ, ihψ];
356|     constructor;
357|     . rintro (hφ | hψ);
358|       . apply T.imp_closed orIntroL hφ;
359|       . apply T.imp_closed orIntroR hψ;
360|     . apply T.prime;
361|   | hand φ ψ ihφ ihψ =>
362|     suffices (φ ∈ T.theory ∧ ψ ∈ T.theory) ↔ φ ⋏ ψ ∈ T.theory by
363|       simpa [Kripke2.Satisfies, ihφ, ihψ];
364|     constructor;
365|     . rintro ⟨hφ, hψ⟩;
366|       apply T.andIR hφ hψ;
367|     . intro h;
368|       constructor;
369|       . apply T.imp_closed andElimL h;
370|       . apply T.imp_closed andElimR h;
371|   | himp φ ψ ihφ ihψ =>
372|     suffices (∀ {U : canonicalModel L}, T ≺ U → φ ∈ U.theory → ψ ∈ U.theory) ↔ φ ➝ ψ ∈ T.theory by
373|       simpa [Kripke2.Satisfies, ihφ, ihψ];
374|     constructor;
375|     . contrapose!;
376|       exact FTheory.lindenbaum T.toFTheory;

