25| lemma KD_subset_of_not_subset_Ver.lemma₁ (hL : L ⊢ φ) (hV : Modal.Ver ⊬ φ) : ∃ ψ, L ⊢ ◇ψ := by
26|   obtain ⟨ψ, ⟨Γ, rfl⟩, h⟩ := Hilbert.NNFormula.exists_CNF φ;
27|   generalize eγ : (⋀Γ.unattach).toFormula = γ at h;
28| 
29|   have : L ⊢ φ.toNNFormula.toFormula ⭤ γ := WeakerThan.pbl h;
30| 
31|   have hγL : γ ∈ L := by sorry;
32|   have hγV : γ ∉ Modal.Ver := by sorry;
33| 
34|   obtain ⟨⟨_, ⟨Δ, rfl⟩⟩, hδΓ, hδL, hδV⟩ : ∃ δ, δ ∈ Γ ∧ δ.1.toFormula ∈ L ∧ δ.1.toFormula ∉ Modal.Ver := by
35|     sorry;
36|   have hΔ₁ : ∀ ψ ∈ Δ, ¬ψ.1.isPrebox := by
37|     rintro ⟨ψ, _⟩ hψ₁ hψ₂;
38|     obtain ⟨ξ, rfl⟩ := NNFormula.exists_isPrebox hψ₂;
39|     have : Modal.Ver ⊢ □ξ.toFormula := by simp;
40|     sorry;
41| 
42|   have : ∃ Γ: List (Formula ℕ), L ⊢ φ ⭤ ⋀Γ := by sorry;
43|   sorry;
