45| lemma KD_subset_of_not_subset_Ver (hV : ¬L ⪯ Modal.Ver) : Modal.KD ⪯ L := by
46|   apply weakerThan_iff.mpr;
47|   intro φ hφ;
48|   replace hφ : Modal.KP ⊢ φ := Entailment.Equiv.iff.mp inferInstance _ |>.mpr hφ;
49|   induction hφ using Hilbert.Normal.rec! with
50|   | axm _ h =>
51|     rcases h with (rfl | rfl);
52|     . simp;
53|     . obtain ⟨ψ, hψ₁, hψ₂⟩ := not_weakerThan_iff.mp hV;
54|       obtain ⟨ξ, hξ⟩ := KD_subset_of_not_subset_Ver.lemma₁ hψ₁ hψ₂;
55|       apply Entailment.mdp! (φ := ◇ξ);
56|       . exact contra! $ axiomK'! $ nec! $ efq!;
57|       . exact hξ;
58|   | mdp hφψ hφ => exact hφψ ⨀ hφ;
59|   | nec hφ => exact Entailment.nec! hφ;
60|   | _ => simp;
61| 
62| lemma KD_subset_of_not_VerFamily (h : ¬L.VerFamily) : Modal.KD ⪯ L := by
63|   apply KD_subset_of_not_subset_Ver;
64|   tauto;
